class EngineeringError extends Error {code       ;path       ;constructor(message       ,path='',code='INVALID_INPUT'){super(message);this.name='EngineeringError';this.code=code;this.path=path;}}
function finite(x       ,path='')        {if(typeof x!=='number'||!Number.isFinite(x))throw new EngineeringError('NaN/Infinity o valor no numérico',path);return x;}
function range(x       ,min       ,max       ,path='')        {finite(x,path);if(x<min||x>max)throw new EngineeringError(`Valor fuera de ${min}…${max}`,path);return x;}
