function infiltrationFlow(ach      ,volume      )               {const a=nonnegative(numberOf(ach,'ACH'),'ACH'),v=nonnegative(numberOf(volume,'m³'),'volumen'),q=a*v/3600;return {value:{value:q,unit:'m³/s',provenance:'calculado',source:'ACH × volumen / 3600'},warnings:[],trace:[trace('infiltration-flow','Infiltración desde ACH','Vdot=ACH Vzona/3600',{ACH:variable(ach),Vzona:variable(volume)},q,'m³/s','12.1')]};}
function supplyFlow(sensible      ,room         ,supply         )                                                         {const Q=nonnegative(numberOf(sensible,'W'),'carga sensible'),dt=positive(numberOf(room.temperature,'°C')-numberOf(supply.temperature,'°C'),'Troom−Tsupply'),cp=1.006+1.86*room.w,m=Q/(1000*cp*dt),v=m*supply.v,water=m*(room.w-supply.w);return {value:{mass:m,volume:v,waterRemoved:water},warnings:[],trace:[trace('supply-mass','Impulsión por carga sensible','m_da=Qs/[1000(1.006+1.86 Wroom)(Troom−Tsupply)]',{Qs:variable(sensible),Wroom:calculated(room.w,'kg_w/kg_da','Estado interior'),Troom:variable(room.temperature),Tsupply:variable(supply.temperature)},m,'kg_da/s','19'),trace('supply-flow','Caudal volumétrico de impulsión','Vdot=m_da v_supply',{m_da:calculated(m,'kg_da/s','supply-mass'),v_supply:calculated(supply.v,'m³/kg_da','Estado de impulsión')},v,'m³/s','19'),trace('water-removed','Extracción de humedad','mdot_water=m_da(Wroom−Wsupply)',{m_da:calculated(m,'kg_da/s','supply-mass'),Wroom:calculated(room.w,'kg_w/kg_da','Interior'),Wsupply:calculated(supply.w,'kg_w/kg_da','Impulsión')},water,'kg_w/s','20')]};}
function moistureGeneration(personsWater       ,equipmentWater       ,infiltrationMass       ,out         ,room         ,directMechanicalMass=0)                {const water=nonnegative(personsWater)+nonnegative(equipmentWater)+(nonnegative(infiltrationMass)+nonnegative(directMechanicalMass))*(out.w-room.w);return {value:water,warnings:[],trace:[trace('water-net','Entrada neta de humedad','mdot_water=Ql_interna/2501000+(m_inf+m_oa_directa)(Wout−Wroom)',{personas:calculated(personsWater,'kg_w/s','Ql,personas / hfg,0'),equipos:calculated(equipmentWater,'kg_w/s','Ql,equipos / hfg,0'),m_inf:calculated(infiltrationMass,'kg_da/s','Infiltración'),m_oa_directa:calculated(directMechanicalMass,'kg_da/s','Ventilación directa al ambiente'),Wout:calculated(out.w,'kg_w/kg_da','Estado exterior'),Wroom:calculated(room.w,'kg_w/kg_da','Interior')},water,'kg_w/s','20',['Conversión de generación latente con hfg,0=2501 kJ/kg según constante del contrato; aire exterior evaluado mediante balance de humedad.'])]};}
function leakage(coefficient       ,exponent       ,pressure      )                {nonnegative(coefficient,'C');range(exponent,.5,1,'n');const dp=numberOf(pressure,'Pa'),q=coefficient*Math.sign(dp)*Math.abs(dp)**exponent;return {value:q,warnings:[],trace:[trace('leak','Fuga power-law','Q=C sgn(ΔP)|ΔP|^n',{C:calculated(coefficient,'m³/(s·Pa^n)','Coeficiente explícitamente ingresado'),n:calculated(exponent,'1','Exponente explícitamente ingresado'),deltaP:variable(pressure)},q,'m³/s','12.2')]};}
function orifice(cd       ,area      ,pressure      ,density       )                {range(cd,0,1,'Cd');const a=nonnegative(numberOf(area,'m²')),dp=numberOf(pressure,'Pa'),rho=positive(density,'ρ'),q=cd*a*Math.sign(dp)*Math.sqrt(2*Math.abs(dp)/rho);return {value:q,warnings:[],trace:[trace('orifice','Flujo por orificio','Q=Cd A sgn(ΔP)√(2|ΔP|/ρ)',{Cd:calculated(cd,'1','Ingresado'),A:variable(area),deltaP:variable(pressure),rho:calculated(rho,'kg/m³','Densidad del estado de flujo')},q,'m³/s','12.3')]};}
