modules["seleccion_equipos"]=(()=>{

const {numberOf,nonnegative,trace,variable,calculated,EngineeringError}=modules["core"];

function selectEquipment(demandTotal      ,demandSensible      ,point                            ,actualOutdoor       ,actualIndoor       ,margin      )                                                                       {const t=nonnegative(numberOf(demandTotal,'W')),s=nonnegative(numberOf(demandSensible,'W')),m=nonnegative(numberOf(margin,'1')),required=t*(1+m);if(!point)return {value:{status:'sin-verificar',required},warnings:[{code:'MISSING_MANUFACTURER_CURVE',path:'equipo',message:'Sin curva de fabricante en condiciones reales: selección sin verificar.'}],trace:[trace('selection','Demanda y margen separado','Qrequerida=Qcarga(1+margen); no modifica el balance',{Qcarga:variable(demandTotal),margen:variable(margin)},required,'W','23,25')]};if(!point.source?.trim()||point.outdoorTemperature!==actualOutdoor||point.indoorTemperature!==actualIndoor)throw new EngineeringError('La capacidad no corresponde al punto real de operación','equipo');nonnegative(point.totalW);nonnegative(point.sensibleW);if(point.sensibleW>point.totalW)throw new EngineeringError('Capacidad sensible > total');return {value:{status:point.totalW>=required&&point.sensibleW>=s*(1+m)?'cumple':'no-cumple',required},warnings:[],trace:[trace('selection','Verificación con ficha del fabricante','Qdisponible ≥ Qrequerida; Qs,disponible ≥ Qs,requerida',{Qcarga:variable(demandTotal),Qs:variable(demandSensible),margen:variable(margin),total:{value:point.totalW,unit:'W',provenance:'biblioteca',source:point.source+' · '+point.model},sensible:{value:point.sensibleW,unit:'W',provenance:'biblioteca',source:point.source+' · '+point.model},Tout:calculated(actualOutdoor,'°C','Punto de operación'),Tin:calculated(actualIndoor,'°C','Punto de operación')},required,'W','23')]};}

return {selectEquipment};})();
